      hu: ["Magasság: 30 méter", "Avatás: 1944. március 30.", "Anyag: helyi márvány", "Bronzszobor súlya: 2 tonna", "Park területe: 1,5 hektár", "Költség: 500.000 dominikai peso (1944)"],
